class Token(BaseModel):
    access_token: str
    token_type: str

class LoginRequest(BaseModel):
    username: str
    password: str


class ForgotPasswordRequest(BaseModel):
    email: str


class ResetPasswordRequest(BaseModel):
    token: str
    new_password: str

def create_access_token(data: dict, expires_delta: Optional[timedelta] = None):
    to_encode = data.copy()
    if expires_delta:
        expire = datetime.utcnow() + expires_delta
    else:
        expire = datetime.utcnow() + timedelta(minutes=15)
    to_encode.update({"exp": expire})
    encoded_jwt = jwt.encode(to_encode, settings.SECRET_KEY, algorithm=settings.ALGORITHM)
    return encoded_jwt


def create_password_reset_token(email: str) -> str:
    expire = datetime.utcnow() + timedelta(minutes=settings.PASSWORD_RESET_TOKEN_EXPIRE_MINUTES)
    payload = {
        "sub": email,
        "purpose": "password_reset",
        "exp": expire,
    }
    return jwt.encode(payload, settings.SECRET_KEY, algorithm=settings.ALGORITHM)


def verify_password_reset_token(token: str) -> Optional[str]:
    try:
        payload = jwt.decode(token, settings.SECRET_KEY, algorithms=[settings.ALGORITHM])
        if payload.get("purpose") != "password_reset":
            return None
        email = payload.get("sub")
        if not email:
            return None
        return str(email)
    except Exception:
        return None


def send_password_reset_email(to_email: str, reset_link: str) -> None:
    content = (
        "You requested a password reset for AI Story.\n\n"
        f"Please open this link to reset your password:\n{reset_link}\n\n"
        f"This link expires in {settings.PASSWORD_RESET_TOKEN_EXPIRE_MINUTES} minutes.\n"
        "If you did not request this, you can ignore this email."
    )
    _send_email_via_runtime_smtp(to_email, "AI Story Password Reset", content)

def authenticate_user(db: Session, username: str, password: str):
    username = str(username or "").strip()
    try:
        # Try by username
        user = db.query(User).filter(User.username == username).first()
        if not user:
            # Try by email
            user = db.query(User).filter(User.email == str(username or "").strip().lower()).first()
    except Exception as exc:
        try:
            db.rollback()
        except Exception:
            pass
        logger.error("DB lookup failed in authenticate_user: %s", type(exc).__name__)
        raise HTTPException(
            status_code=503,
            detail="Database temporarily unavailable, please retry",
        )
    
    if not user:
        return None
    if not verify_password(password, user.hashed_password):
        return None
    return user


def _is_maintenance_active_for_login(db: Session) -> bool:
    try:
        status = _resolve_maintenance_config_raw(db)
        return bool(status.get("is_active", False))
    except Exception:
        return False

@router.post("/login/access-token", response_model=Token)
@limiter.limit(settings.RATE_LIMIT_LOGIN)
def login_access_token(request: Request, form_data: OAuth2PasswordRequestForm = Depends(), db: Session = Depends(get_db)):
    """
    OAuth2 compatible token login, get an access token for future requests.
    Requires 'username' and 'password' as form fields.
    """
    user = authenticate_user(db, form_data.username, form_data.password)
    if not user:
        raise HTTPException(status_code=400, detail="Incorrect email or password")
    if _is_maintenance_active_for_login(db) and (not bool(getattr(user, "is_superuser", False))):
        raise HTTPException(status_code=403, detail="System is under maintenance. Only system administrators can login now")
    if (
        user.account_status == -1
        and (not _is_user_enabled(user.is_active))
        and (not bool(getattr(user, "is_superuser", False)))
    ):
        raise HTTPException(status_code=403, detail="Email verification required. Please verify your email code before login")
    if not _is_user_enabled(user.is_active):
        raise HTTPException(status_code=403, detail="User is disabled")

    try:
        _seed_default_system_settings_for_user(db, user.id)
        db.commit()
    except Exception as e:
        db.rollback()
        logger.warning("Failed to seed default API settings on login | user_id=%s error=%s", user.id, e)
    
    # Log Successful Login
    log_action(db, user_id=user.id, user_name=user.username, action="LOGIN", details="User logged in via OAuth2 Form")
    
    access_token_expires = timedelta(minutes=settings.ACCESS_TOKEN_EXPIRE_MINUTES)
    cache_user_identity(user)
    access_token = create_access_token(
        data={
            "sub": user.username,
            "uid": user.id,
            "uname": user.username,
            "is_superuser": bool(getattr(user, "is_superuser", False)),
        },
        expires_delta=access_token_expires
    )
    return {"access_token": access_token, "token_type": "bearer"}

